class Book {
  private String isbn;         // unique catalog identifier
  private String title;
  private List<Author> authors;
  private List<BookItem> copies; // physical copies
}

class BookItem {
  private String barcode;      // unique physical copy
  private Book book;           // which book this is
  private BookStatus status;   // AVAILABLE, CHECKED_OUT, RESERVED
  private Member checkedOutBy;
  private LocalDate dueDate;
}

class BookLending {            // transaction record
  private BookItem bookItem;
  private Member member;
  private LocalDate checkoutDate;
  private LocalDate returnDate;
}

class Book implements Observable {
  private Queue<Reservation> reservationQueue = new LinkedList<>();
  private List<Observer> observers = new ArrayList<>(); // notification listeners

  public void addReservation(Member member) {
    reservationQueue.offer(new Reservation(member, this, LocalDateTime.now()));
  }

  public void onBookItemReturned(BookItem item) {
    if (!reservationQueue.isEmpty()) {
      Reservation next = reservationQueue.poll();
      notifyObservers(new ReservationAvailableEvent(next.getMember(), item));
      // or: item.reserveFor(next.getMember());
    }
  }
}

interface SearchCriteria {
  boolean matches(Book book);
}

class TitleSearchCriteria implements SearchCriteria {
  private final String query;
  public boolean matches(Book book) {
    return book.getTitle().toLowerCase().contains(query.toLowerCase());
  }
}

class LibraryCatalog {
  private List<Book> books;

  public List<Book> search(SearchCriteria criteria) {
    return books.stream()
        .filter(criteria::matches)
        .collect(Collectors.toList());
  }
}

interface FineCalculator {
  BigDecimal calculate(BookLending lending, LocalDate returnDate);
}

class StandardFineCalculator implements FineCalculator {
  private static final BigDecimal DAILY_RATE = new BigDecimal("5.00");

  public BigDecimal calculate(BookLending lending, LocalDate returnDate) {
    long overdueDays = ChronoUnit.DAYS.between(
        lending.getDueDate(), returnDate);
    if (overdueDays <= 0) return BigDecimal.ZERO;
    return DAILY_RATE.multiply(BigDecimal.valueOf(overdueDays));
  }
}
